fn is_palindrome(text: Vec<char>) -> bool {
    let n = text.len();
    for i in 0..n / 2 {
        let left = text[i].to_ascii_lowercase();
        let right = text[n - 1 - i].to_ascii_lowercase();
        if left != right {
            return false;
        }
    }
    true
}